int sparse_case_load_fixed(float *a, float *dense_w, sparse_weights *s)
{
    if (!a || !dense_w || !s)
        return SPARSE_ERROR;

    memset(s, 0, sizeof(*s));
    s->k = HW1_K;
    s->n = HW1_N;
    s->nnzb = HW1_NNZB;
    s->block_col_ptr = malloc(sizeof(case_block_col_ptr));
    s->block_row_idx = malloc(s->nnzb * sizeof(*s->block_row_idx));
    s->block_values = malloc(16 * s->nnzb * sizeof(*s->block_values));
    if (!s->block_col_ptr || !s->block_row_idx || !s->block_values) {
        sparse_weights_destroy(s);
        return SPARSE_ERROR;
    }

    memcpy(a, case_a, sizeof(case_a));
    memcpy(s->block_col_ptr, case_block_col_ptr, sizeof(case_block_col_ptr));
    memcpy(s->block_row_idx, case_block_row_idx, sizeof(case_block_row_idx));
    memcpy(s->block_values, case_block_values, sizeof(case_block_values));
    memset(dense_w, 0, HW1_K * HW1_N * sizeof(*dense_w));

    for (size_t g = 0; g < HW1_N / 4; ++g)
        for (size_t p = s->block_col_ptr[g]; p < s->block_col_ptr[g + 1]; ++p) {
            size_t k0 = 4 * (size_t)s->block_row_idx[p];
            for (size_t r = 0; r < 4; ++r)
                for (size_t col = 0; col < 4; ++col)
                    dense_w[(k0 + r) * HW1_N + 4 * g + col] =
                        s->block_values[16 * p + 4 * r + col];
        }
    return SPARSE_OK;
}
